/**
 * Generate crawlable, human-readable pages alongside the Vite application.
 * Run after `vite build`; the script library manifest is generated by prebuild.
 */
import fs from 'node:fs';
import path from 'node:path';
import crypto from 'node:crypto';
import { fileURLToPath } from 'node:url';
import ts from 'typescript';
import {
  SITE_URL, DEFAULT_LANGUAGE, LANGUAGES, LANG_TO_BCP47, LANGUAGE_URLS,
  META, STRUCTURED_DATA, PAGES, OG_IMAGE, OG_IMAGE_WIDTH, OG_IMAGE_HEIGHT,
} from '../src/utils/seoConfig.js';

const ROOT = path.resolve(path.dirname(fileURLToPath(import.meta.url)), '..');
const DOCS_DIR = path.join(ROOT, 'docs');
const SCRIPTS_OUT_DIR = path.join(DOCS_DIR, 'scripts');
const MANIFEST_PATH = path.join(SCRIPTS_OUT_DIR, 'json', 'manifest.json');
const GA_ID = process.env.VITE_GA_MEASUREMENT_ID || 'G-VB8HT63ZX6';
const DRY_RUN = process.argv.includes('--dry-run') || process.env.DRY_RUN === '1';

function escapeHtml(value) {
  return String(value ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;')
    .replace(/>/g, '&gt;').replace(/"/g, '&quot;').replace(/'/g, '&#39;');
}

function jsonForHtml(value) {
  return JSON.stringify(value, null, 2).replace(/</g, '\\u003c');
}

function plainText(value) {
  return String(value ?? '').replace(/<[^>]*>/g, ' ').replace(/\s+/g, ' ').trim();
}

function summary(value, maxLength = 130) {
  const text = plainText(value);
  return text.length > maxLength ? `${text.slice(0, maxLength - 1).trimEnd()}…` : text;
}

function writeFile(outPath, content) {
  if (DRY_RUN) {
    console.log(`[generate-seo-html] dry-run: ${path.relative(ROOT, outPath)}`);
    return;
  }
  fs.mkdirSync(path.dirname(outPath), { recursive: true });
  fs.writeFileSync(outPath, content, 'utf8');
}

function slugify(text) {
  return String(text).toLowerCase().replace(/[^a-z0-9]+/g, '-').replace(/^-+|-+$/g, '') || 'script';
}

// Preserve the existing public URLs.
function entrySlug(entry) {
  const category = slugify(entry.category || 'custom');
  const hash = crypto.createHash('md5').update(entry.jsonUrl).digest('hex').slice(0, 8);
  const name = slugify(entry.name || '');
  if (name.length > 2) return `${category}-${name.slice(0, 20)}-${hash}`;
  if (entry.nameEn) {
    const englishName = slugify(entry.nameEn);
    if (englishName.length > 2) return `${category}-${englishName.slice(0, 20)}-${hash}`;
  }
  return `${category}-${hash}`;
}

function entryUrl(entry) {
  return `${SITE_URL}/scripts/${entrySlug(entry)}.html`;
}

function previewUrl(entry) {
  return `${SITE_URL}/#/repo/preview?json=${encodeURIComponent(assetUrl(entry.jsonUrl))}`;
}

function assetUrl(assetPath) {
  return assetPath.split('/').map(encodeURIComponent).join('/');
}

function buildHreflangLinks() {
  return [
    ...LANGUAGES.map((lang) => `  <link rel="alternate" hreflang="${LANG_TO_BCP47[lang]}" href="${LANGUAGE_URLS[lang]}" />`),
    `  <link rel="alternate" hreflang="x-default" href="${SITE_URL}/" />`,
  ].join('\n');
}

function buildGaScript() {
  return `  <script async src="https://www.googletagmanager.com/gtag/js?id=${escapeHtml(GA_ID)}"></script>
  <script>
    window.dataLayer = window.dataLayer || [];
    function gtag(){dataLayer.push(arguments);}
    gtag('js', new Date());
    gtag('config', ${JSON.stringify(GA_ID)}, { page_location: window.location.href, page_title: document.title });
  </script>`;
}

function structuredData(data) {
  return `  <script type="application/ld+json">\n${jsonForHtml(data)}\n  </script>`;
}

const pageStyle = `
  :root { color-scheme: light; font-family: "Source Han Serif SC", "Microsoft YaHei", Georgia, serif; }
  body { margin: 0; background: #f6f1dc; color: #2c2416; line-height: 1.7; }
  header, main, footer { max-width: 960px; margin: auto; padding: 1rem 1.25rem; }
  header { border-bottom: 1px solid #c9bda2; }
  nav { display: flex; flex-wrap: wrap; align-items: center; gap: 1rem; }
  nav a:first-child { font-weight: bold; }
  a { color: #075780; text-underline-offset: 0.15em; overflow-wrap: anywhere; }
  a:focus-visible { outline: 3px solid #607963; outline-offset: 3px; }
  h1, h2, h3 { line-height: 1.3; }
  h1 { font-size: clamp(1.7rem, 5vw, 2.5rem); margin: 1rem 0; }
  section { margin: 2rem 0; }
  .lead { font-size: 1.1rem; max-width: 75ch; }
  .actions { display: flex; flex-wrap: wrap; gap: 0.75rem; margin: 1.25rem 0; }
  .button { display: inline-block; background: #075780; color: white; padding: 0.6rem 1rem; border-radius: 6px; text-decoration: none; }
  .button:hover { background: #064968; }
  .muted { color: #51483d; }
  .description { white-space: pre-wrap; overflow-wrap: anywhere; }
  .roles { display: flex; flex-wrap: wrap; gap: 0.4rem 1.2rem; padding-left: 1.25rem; }
  .directory li { margin-bottom: 0.75rem; }
  footer { border-top: 1px solid #c9bda2; font-size: 0.9rem; }
`;

function staticPage({ lang, title, description, canonical, body, jsonLd, alternates = false }) {
  return `<!doctype html>
<html lang="${escapeHtml(lang)}">
<head>
  <meta charset="UTF-8" />
  <meta name="viewport" content="width=device-width, initial-scale=1" />
  <title>${escapeHtml(title)}</title>
  <meta name="description" content="${escapeHtml(description)}" />
  <meta name="robots" content="index, follow" />
  <link rel="canonical" href="${escapeHtml(canonical)}" />
${alternates ? buildHreflangLinks() : ''}
  <meta property="og:type" content="website" />
  <meta property="og:title" content="${escapeHtml(title)}" />
  <meta property="og:description" content="${escapeHtml(description)}" />
  <meta property="og:url" content="${escapeHtml(canonical)}" />
  <meta property="og:image" content="${OG_IMAGE}" />
  <meta property="og:image:width" content="${OG_IMAGE_WIDTH}" />
  <meta property="og:image:height" content="${OG_IMAGE_HEIGHT}" />
  <meta name="twitter:card" content="summary_large_image" />
  <meta name="twitter:title" content="${escapeHtml(title)}" />
  <meta name="twitter:description" content="${escapeHtml(description)}" />
  <meta name="twitter:image" content="${OG_IMAGE}" />
  <link rel="icon" href="/32x32.ico" />
  <style>${pageStyle}</style>
${jsonLd ? structuredData(jsonLd) : ''}
${buildGaScript()}
</head>
<body>
${body}
</body>
</html>
`;
}

function stripDynamicTags(html) {
  return html
    .replace(/<link rel="alternate" hreflang="[^"]*" href="[^"]*" \/>\n?/g, '')
    .replace(/<link rel="canonical" href="[^"]*" \/>\n?/g, '')
    .replace(/<script type="application\/ld\+json">[\s\S]*?<\/script>\n?/g, '')
    .replace(/<script async src="https:\/\/www\.googletagmanager\.com\/gtag\/js\?id=[^"]*"><\/script>\n?/g, '')
    .replace(/<script>\s*window\.dataLayer[\s\S]*?gtag\('config',[\s\S]*?<\/script>\n?/g, '')
    .replace(/<style id="app-startup-styles">[\s\S]*?<\/style>\n?/g, '')
    .replace(/<meta property="og:locale:alternate" content="[^"]*" \/>\n?/g, '');
}

