function normalizeId(id) {
  return String(id).toLowerCase().replace(/[^a-z0-9\u4e00-\u9fff]/g, '');
}

function readCharacterNames() {
  const entries = new Map();
  const roles = JSON.parse(fs.readFileSync(path.join(ROOT, 'src/data/sources/roles.json'), 'utf8'));
  for (const role of roles) entries.set(normalizeId(role.id), { en: role.name, team: role.team });

  // Read Chinese names from the project's canonical TypeScript data without evaluating it.
  const source = fs.readFileSync(path.join(ROOT, 'src/data/characters/characters.ts'), 'utf8');
  const file = ts.createSourceFile('characters.ts', source, ts.ScriptTarget.Latest, true, ts.ScriptKind.TS);
  function visit(node) {
    if (ts.isVariableDeclaration(node) && node.name.getText(file) === 'ZH_CORE_CHARACTERS'
        && node.initializer && ts.isObjectLiteralExpression(node.initializer)) {
      for (const property of node.initializer.properties) {
        if (!ts.isPropertyAssignment(property) || !ts.isObjectLiteralExpression(property.initializer)) continue;
        const id = ts.isStringLiteral(property.name) || ts.isIdentifier(property.name) ? property.name.text : '';
        const fields = {};
        for (const field of property.initializer.properties) {
          if (ts.isPropertyAssignment(field) && ts.isStringLiteral(field.initializer)) {
            fields[field.name.getText(file).replace(/^["']|["']$/g, '')] = field.initializer.text;
          }
        }
        const key = normalizeId(id);
        if (key && fields.name) entries.set(key, { ...entries.get(key), cn: fields.name, team: fields.team || entries.get(key)?.team });
      }
    }
    ts.forEachChild(node, visit);
  }
  visit(file);
  return entries;
}

const TEAM_LABELS = {
  townsfolk: '镇民 / Townsfolk', outsider: '外来者 / Outsiders',
  minion: '爪牙 / Minions', demon: '恶魔 / Demons',
  traveler: '旅行者 / Travelers', fabled: '传奇角色 / Fabled', loric: '神话角色 / Loric',
};

function readScriptRoles(entry, characterNames) {
  const file = path.resolve(DOCS_DIR, `.${entry.jsonUrl}`);
  const allowedRoot = path.resolve(SCRIPTS_OUT_DIR, 'json') + path.sep;
  if (!file.startsWith(allowedRoot)) throw new Error(`Invalid script path: ${entry.jsonUrl}`);
  const data = JSON.parse(fs.readFileSync(file, 'utf8'));
  if (!Array.isArray(data)) return [];
  return data.flatMap((item) => {
    if (typeof item !== 'string' && (!item || typeof item !== 'object' || item.id === '_meta')) return [];
    const id = typeof item === 'string' ? item : item.id;
    const known = characterNames.get(normalizeId(id)) || {};
    const team = (typeof item === 'object' && item.team) || known.team;
    if (!TEAM_LABELS[team]) return [];
    const name = (typeof item === 'object' && typeof item.name === 'string' && item.name) || known.cn || known.en || id;
    const englishName = known.en && known.en !== name ? known.en : '';
    return [{ team, name, englishName }];
  });
}

const CATEGORY_LABELS = { official: '官方剧本', official_mix: '官方角色混编', custom: '自定义剧本' };

function generateScriptPage(entry, characterNames) {
  const name = entry.name || entry.file;
  const englishName = entry.nameEn && entry.nameEn !== name ? entry.nameEn : '';
  const author = entry.author || '未知';
  const category = CATEGORY_LABELS[entry.category] || '剧本';
  const canonical = entryUrl(entry);
  const title = `${name}${englishName ? `（${englishName}）` : ''} — 血染钟楼剧本`;
  const description = summary(entry.description || `${name}${englishName ? `（${englishName}）` : ''}，${category}，作者：${author}。查看角色、预览剧本、下载 JSON 或打印为 PDF。`);
  const roles = readScriptRoles(entry, characterNames);
  const grouped = Object.entries(TEAM_LABELS).map(([team, label]) => {
    const members = roles.filter((role) => role.team === team);
    if (!members.length) return '';
    return `<h3>${label}</h3><ul class="roles">${members.map((role) => `<li>${escapeHtml(role.name)}${role.englishName ? ` <span class="muted">(${escapeHtml(role.englishName)})</span>` : ''}</li>`).join('')}</ul>`;
  }).join('');
  const body = `<header><nav aria-label="导航"><a href="/">BOTC 剧本工具</a><a href="/scripts/">剧本目录</a><a href="/zh-cn/">使用说明</a></nav></header>
<main>
  <p><a href="/scripts/">剧本目录</a> / ${escapeHtml(category)}</p>
  <h1>${escapeHtml(name)}${englishName ? ` <span class="muted">（${escapeHtml(englishName)}）</span>` : ''}</h1>
  <p class="muted">${escapeHtml(category)} · 作者：${escapeHtml(author)}</p>
  ${entry.description ? `<section><h2>剧本介绍</h2><p class="description">${escapeHtml(entry.description)}</p></section>` : ''}
  <div class="actions"><a class="button" href="${escapeHtml(previewUrl(entry))}">预览和打印剧本</a><a href="${escapeHtml(assetUrl(entry.jsonUrl))}">查看剧本 JSON</a></div>
  ${grouped ? `<section><h2>角色列表</h2>${grouped}</section>` : ''}
  <p>在剧本工具中可以预览版面、导出图片，或通过浏览器打印和保存 PDF。</p>
</main><footer><a href="/scripts/">返回剧本目录</a> · <a href="/">打开剧本工具</a></footer>`;
  const jsonLd = {
    '@context': 'https://schema.org', '@type': 'CreativeWork', name,
    ...(englishName ? { alternateName: englishName } : {}),
    description, url: canonical,
    inLanguage: 'zh-CN', isAccessibleForFree: true,
  };
  return staticPage({ lang: 'zh-CN', title, description, canonical, body, jsonLd });
}

function generateDirectory(entries) {
  const groups = Object.entries(CATEGORY_LABELS).map(([category, label]) => {
    const items = entries.filter((entry) => entry.category === category);
    if (!items.length) return '';
    return `<section><h2>${label}</h2><ul class="directory">${items.map((entry) =>
      `<li><a href="${escapeHtml(entryUrl(entry))}">${escapeHtml(entry.name)}${entry.nameEn ? `（${escapeHtml(entry.nameEn)}）` : ''}</a> — ${escapeHtml(entry.author || '未知')}${entry.description ? `<br><span class="muted">${escapeHtml(summary(entry.description, 100))}</span>` : ''}</li>`
    ).join('')}</ul></section>`;
  }).join('');
  const title = '血染钟楼剧本目录 — 官方与自定义剧本';
  const description = '浏览血染钟楼官方、官方角色混编和自定义剧本，查看角色列表，并预览或下载剧本 JSON。';
  const body = `<header><nav aria-label="导航"><a href="/">BOTC 剧本工具</a><a href="/zh-cn/">使用说明</a><a href="/es/" lang="es">Español</a></nav></header>
<main><h1>血染钟楼剧本目录</h1><p class="lead">${description}</p>
<p><a href="/#/repo">打开交互式剧本仓库</a> · <a href="/">制作自己的剧本</a></p>${groups}</main>
<footer><a href="/">打开剧本工具</a></footer>`;
  const jsonLd = {
    '@context': 'https://schema.org', '@type': 'CollectionPage', name: title,
    description, url: `${SITE_URL}/scripts/`, inLanguage: 'zh-CN',
    mainEntity: { '@type': 'ItemList', itemListElement: entries.map((entry, index) => ({
      '@type': 'ListItem', position: index + 1, name: entry.name, url: entryUrl(entry),
    })) },
  };
  return staticPage({ lang: 'zh-CN', title, description, canonical: `${SITE_URL}/scripts/`, body, jsonLd });
}

function generateSitemapXml(entries) {
  const localePaths = new Set(['/', '/zh-cn/', '/es/']);
  const urls = PAGES.map(({ path: pagePath }) => {
    const loc = `${SITE_URL}${pagePath}`;
    const alternates = localePaths.has(pagePath)
      ? [...LANGUAGES.map((lang) => `    <xhtml:link rel="alternate" hreflang="${LANG_TO_BCP47[lang]}" href="${LANGUAGE_URLS[lang]}"/>`),
        `    <xhtml:link rel="alternate" hreflang="x-default" href="${SITE_URL}/"/>`].join('\n')
      : '';
    return `  <url>\n    <loc>${loc}</loc>\n${alternates ? `${alternates}\n` : ''}  </url>`;
  });
  for (const entry of entries) urls.push(`  <url><loc>${escapeHtml(entryUrl(entry))}</loc></url>`);
  return `<?xml version="1.0" encoding="UTF-8"?>\n<urlset xmlns="http://www.sitemaps.org/schemas/sitemap/0.9" xmlns:xhtml="http://www.w3.org/1999/xhtml">\n${urls.join('\n')}\n</urlset>\n`;
}

function generateRobotsTxt() {
  return `User-agent: *
Allow: /

# Search and AI crawlers are welcome.
User-agent: OAI-SearchBot
Allow: /

User-agent: ChatGPT-User
Allow: /

User-agent: GPTBot
Allow: /

User-agent: PerplexityBot
Allow: /

User-agent: ClaudeBot
Allow: /

User-agent: anthropic-ai
Allow: /

Sitemap: ${SITE_URL}/sitemap.xml
`;
}

function generateLlmsTxt(entries, full = false) {
  const listing = entries.map((entry) =>
    `- [${entry.name}](${entryUrl(entry)})${entry.nameEn ? ` (${entry.nameEn})` : ''} — ${entry.author || 'Community'}${entry.description ? `: ${summary(entry.description, full ? 500 : 120)}` : ''}`
  ).join('\n');
  const faq = full ? `\n## Frequently asked questions\n\n${META.en.faq.map((item) => `### ${item.question}\n\n${item.answer}`).join('\n\n')}\n` : '';
  return `# Blood on the Clocktower Script Tool

> A free browser-based editor for creating, formatting and printing Blood on the Clocktower scripts.

- [Open the editor](${SITE_URL}/)
- [中文使用说明](${LANGUAGE_URLS.cn})
- [Guía en español](${LANGUAGE_URLS.es})
- [Script directory](${SITE_URL}/scripts/)
- [Source code](https://github.com/LiWeny16/botc-script-tool)

## Features

${META.en.featureList.map((item) => `- ${item}`).join('\n')}

The core editor can be used without an account. Optional cloud features require sign-in.
${faq}
## Script directory

${listing}
`;
}

function main() {
  const indexPath = path.join(DOCS_DIR, 'index.html');
  const sourceHtml = fs.readFileSync(indexPath, 'utf8');
  const entries = JSON.parse(fs.readFileSync(MANIFEST_PATH, 'utf8')).scripts;
  if (!Array.isArray(entries)) throw new Error('Script manifest is missing its scripts array');
  const characterNames = readCharacterNames();

  writeFile(indexPath, generateRootHtml(sourceHtml));
  writeFile(path.join(DOCS_DIR, 'zh-cn', 'index.html'), generateLanguagePage('cn'));
  writeFile(path.join(DOCS_DIR, 'es', 'index.html'), generateLanguagePage('es'));
  writeFile(path.join(SCRIPTS_OUT_DIR, 'index.html'), generateDirectory(entries));
  for (const entry of entries) writeFile(path.join(SCRIPTS_OUT_DIR, `${entrySlug(entry)}.html`), generateScriptPage(entry, characterNames));
  writeFile(path.join(DOCS_DIR, 'sitemap.xml'), generateSitemapXml(entries));
  writeFile(path.join(DOCS_DIR, 'robots.txt'), generateRobotsTxt());
  writeFile(path.join(DOCS_DIR, 'llms.txt'), generateLlmsTxt(entries));
  writeFile(path.join(DOCS_DIR, 'llms-full.txt'), generateLlmsTxt(entries, true));
  writeFile(path.join(DOCS_DIR, '.nojekyll'), '');
  console.log(`[generate-seo-html] Generated ${entries.length} script pages, directory, localized pages and sitemap.`);
}

main();
